import { useState, useEffect, useCallback, useRef } from 'react';
import { CodigoDoEncontro } from '../api/types';
import { api } from '../api/client';

export function useCodigoEncontro(encontroId: string | undefined, apiClient = api) {
  const [codigoEncontro, setCodigoEncontro] = useState<CodigoDoEncontro | null>(null);
  const [loading, setLoading] = useState<boolean>(false);
  const [error, setError] = useState<{ erro: string; mensagem: string } | null>(null);
  const [foraDaJanela, setForaDaJanela] = useState<boolean>(false);
  const [atividadeCancelada, setAtividadeCancelada] = useState<boolean>(false);

  const timeoutRef = useRef<NodeJS.Timeout | null>(null);

  const clearTimer = () => {
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
      timeoutRef.current = null;
    }
  };

  const fetchCodigo = useCallback(async () => {
    if (!encontroId) {
      setCodigoEncontro(null);
      setLoading(false);
      setError(null);
      setForaDaJanela(false);
      setAtividadeCancelada(false);
      clearTimer();
      return;
    }

    setLoading(true);
    setError(null);
    setForaDaJanela(false);
    setAtividadeCancelada(false);

    try {
      const res = await apiClient.getCodigoEncontro(encontroId);
      setCodigoEncontro(res);
      setLoading(false);

      clearTimer();
      if (res.trocaEm) {
        const trocaTime = new Date(res.trocaEm).getTime();
        const now = Date.now();
        const delay = Math.max(1000, trocaTime - now);

        timeoutRef.current = setTimeout(() => {
          fetchCodigo();
        }, delay);
      }
    } catch (err: any) {
      setLoading(false);
      const erroCode = err.erro || 'ERRO_DESCONHECIDO';
      const mensagem = err.mensagem || err.message || 'Erro ao buscar código do encontro';

      if (erroCode === 'FORA_DA_JANELA') {
        setForaDaJanela(true);
        setError({ erro: erroCode, mensagem });
        clearTimer();
      } else if (erroCode === 'ATIVIDADE_CANCELADA') {
        setAtividadeCancelada(true);
        setError({ erro: erroCode, mensagem });
        clearTimer();
      } else {
        setError({ erro: erroCode, mensagem });
        clearTimer();
      }
    }
  }, [encontroId, apiClient]);

  useEffect(() => {
    fetchCodigo();
    return () => {
      clearTimer();
    };
  }, [fetchCodigo]);

  return {
    codigoEncontro,
    loading,
    error,
    foraDaJanela,
    atividadeCancelada,
    reload: fetchCodigo,
  };
}

import React from 'react';
import { useCodigoEncontro } from '../hooks/useCodigoEncontro';
import { api } from '../api/client';
import { formatarHoraBrasilia } from '../utils/date';

interface CodigoEncontroProps {
  encontroId?: string;
  id?: string;
  apiClient?: typeof api;
}

export function CodigoEncontro({
  encontroId,
  id,
  apiClient = api,
}: CodigoEncontroProps) {
  const targetId = encontroId || id;
  const {
    codigoEncontro,
    loading,
    error,
    foraDaJanela,
    atividadeCancelada,
  } = useCodigoEncontro(targetId, apiClient);

  return (
    <section className="codigo-encontro-container" data-testid="codigo-encontro-container">
      <div className="page-heading">
        <div>
          <span className="eyebrow">Organização do encontro</span>
          <h2>Código de Verificação</h2>
          <p>Exibição em tempo real do código atual para registro de presença.</p>
        </div>
      </div>

      {loading && (
        <div className="state-message state-message--loading" role="status" aria-live="polite">
          <span className="loading-indicator" aria-hidden="true" />
          <span>Carregando código do encontro...</span>
        </div>
      )}

      {foraDaJanela && error && (
        <div className="error-message error-message--fora-janela" role="alert" data-testid="error-fora-janela">
          <strong>Fora do horário permitido.</strong>
          <span>{error.mensagem}</span>
        </div>
      )}

      {atividadeCancelada && error && !foraDaJanela && (
        <div className="error-message error-message--cancelada" role="alert" data-testid="error-cancelada">
          <strong>Atividade cancelada.</strong>
          <span>{error.mensagem}</span>
        </div>
      )}

      {error && !foraDaJanela && !atividadeCancelada && (
        <div className="error-message" role="alert" data-testid="error-generico">
          <strong>Não foi possível carregar o código do encontro.</strong>
          <span>
            Erro ({error.erro}): {error.mensagem}
          </span>
        </div>
      )}

      {!loading && !error && codigoEncontro && (
        <div className="codigo-destaque-panel" data-testid="codigo-destaque">
          <div className="codigo-destaque-card">
            <span className="codigo-destaque-label">Código atual do encontro</span>
            <strong className="codigo-destaque-valor" data-testid="codigo-valor">
              {codigoEncontro.codigo}
            </strong>
          </div>

          <div className="proxima-troca-info" data-testid="proxima-troca">
            <span className="proxima-troca-icon" aria-hidden="true">⏱</span>
            <span>
              Próxima troca em: <strong>{formatarHoraBrasilia(codigoEncontro.trocaEm)}</strong>
            </span>
          </div>
        </div>
      )}

      {!loading && !error && !codigoEncontro && targetId && (
        <div className="empty-message" role="status" aria-live="polite">
          <strong>Nenhum código disponível</strong>
          <p>Não foi possível obter o código para este encontro no momento.</p>
        </div>
      )}
    </section>
  );
}

import { describe, it, expect, beforeEach, vi, afterEach } from 'vitest';
import { render, screen, waitFor } from '@testing-library/react';
import { CodigoEncontro } from './CodigoEncontro';
import { api } from '../api/client';

describe('CodigoEncontro Component', () => {
  beforeEach(() => {
    vi.restoreAllMocks();
  });

  afterEach(() => {
    vi.useRealTimers();
  });

  it('deve exibir indicador de carregamento ao buscar o código do encontro', async () => {
    let resolvePromise: any;
    const pendingPromise = new Promise((resolve) => {
      resolvePromise = resolve;
    });
    const fakeClient = {
      ...api,
      getCodigoEncontro: vi.fn().mockReturnValue(pendingPromise),
    };

    render(<CodigoEncontro encontroId="enc_1" apiClient={fakeClient} />);

    expect(screen.getByText('Carregando código do encontro...')).toBeInTheDocument();

    resolvePromise({
      encontroId: 'enc_1',
      codigo: 'ABC123',
      trocaEm: '2026-10-19T10:05:00-03:00',
      validoAte: '2026-10-19T10:10:00-03:00',
    });
  });

  it('deve exibir o código em destaque e a próxima troca com sucesso', async () => {
    const fakeClient = {
      ...api,
      getCodigoEncontro: vi.fn().mockResolvedValue({
        encontroId: 'enc_1',
        codigo: 'K7M2QX',
        trocaEm: '2026-10-19T10:05:00-03:00',
        validoAte: '2026-10-19T10:10:00-03:00',
      }),
    };

    render(<CodigoEncontro encontroId="enc_1" apiClient={fakeClient} />);

    expect(await screen.findByTestId('codigo-valor')).toHaveTextContent('K7M2QX');
    expect(screen.getByTestId('proxima-troca')).toBeInTheDocument();
  });

  it('deve atualizar automaticamente o código buscando o próximo quando o tempo de trocaEm for atingido', async () => {
    vi.useFakeTimers();
    vi.setSystemTime(new Date('2026-10-19T10:00:00-03:00'));

    const getCodigoMock = vi.fn()
      .mockResolvedValueOnce({
        encontroId: 'enc_1',
        codigo: 'CODE1',
        trocaEm: '2026-10-19T10:01:00-03:00', // 1 minute from 10:00
        validoAte: '2026-10-19T10:02:00-03:00',
      })
      .mockResolvedValueOnce({
        encontroId: 'enc_1',
        codigo: 'CODE2',
        trocaEm: '2026-10-19T10:02:00-03:00',
        validoAte: '2026-10-19T10:03:00-03:00',
      });

    const fakeClient = {
      ...api,
      getCodigoEncontro: getCodigoMock,
    };

    render(<CodigoEncontro encontroId="enc_1" apiClient={fakeClient} />);

    expect(await screen.findByTestId('codigo-valor')).toHaveTextContent('CODE1');
    expect(getCodigoMock).toHaveBeenCalledTimes(1);

    // Advance timers by 60 seconds (trocaEm delay)
    vi.advanceTimersByTime(60000);

    await waitFor(() => {
      expect(screen.getByTestId('codigo-valor')).toHaveTextContent('CODE2');
    });

    expect(getCodigoMock).toHaveBeenCalledTimes(2);
  });

  it('deve tratar o erro FORA_DA_JANELA mostrando mensagem clara e sem tentar novas chamadas', async () => {
    vi.useFakeTimers();
    const getCodigoMock = vi.fn().mockRejectedValue({
      erro: 'FORA_DA_JANELA',
      mensagem: 'Fora do horário permitido para este encontro',
    });

    const fakeClient = {
      ...api,
      getCodigoEncontro: getCodigoMock,
    };

    render(<CodigoEncontro encontroId="enc_1" apiClient={fakeClient} />);

    expect(await screen.findByTestId('error-fora-janela')).toBeInTheDocument();
    expect(screen.getByText('Fora do horário permitido.')).toBeInTheDocument();
    expect(screen.getByText('Fora do horário permitido para este encontro')).toBeInTheDocument();
    expect(getCodigoMock).toHaveBeenCalledTimes(1);

    // Advance time to verify no further calls are made
    vi.advanceTimersByTime(120000);
    expect(getCodigoMock).toHaveBeenCalledTimes(1);
  });

  it('deve tratar o erro ATIVIDADE_CANCELADA mostrando mensagem de que a atividade foi cancelada', async () => {
    const fakeClient = {
      ...api,
      getCodigoEncontro: vi.fn().mockRejectedValue({
        erro: 'ATIVIDADE_CANCELADA',
        mensagem: 'A atividade deste encontro foi cancelada',
      }),
    };

    render(<CodigoEncontro encontroId="enc_1" apiClient={fakeClient} />);

    expect(await screen.findByTestId('error-cancelada')).toBeInTheDocument();
    expect(screen.getByText('Atividade cancelada.')).toBeInTheDocument();
    expect(screen.getByText('A atividade deste encontro foi cancelada')).toBeInTheDocument();
  });

  it('deve tratar erro de rede genérico', async () => {
    const fakeClient = {
      ...api,
      getCodigoEncontro: vi.fn().mockRejectedValue({
        erro: 'ERRO_DE_REDE',
        mensagem: 'Falha de comunicação com o servidor',
      }),
    };

    render(<CodigoEncontro encontroId="enc_1" apiClient={fakeClient} />);

    expect(await screen.findByTestId('error-generico')).toBeInTheDocument();
    expect(screen.getByText(/ERRO_DE_REDE/)).toBeInTheDocument();
    expect(screen.getByText(/Falha de comunicação com o servidor/)).toBeInTheDocument();
  });
});

